def s(en,bn,l):return en if l=='en' else bn
def E(x):return html.escape(str(x),quote=True)
def ic(name,size=''):
 return f'<svg aria-hidden="true" {size} xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">{ICON_PATHS.get(name,ICON_PATHS["check"])}</svg>'
def path_for(lang,slug):return posixpath.join(lang,slug) if slug else lang
def href(lang,slug,dest='',destlang=None):
 destlang=destlang or lang
 r=posixpath.relpath(path_for(destlang,dest),path_for(lang,slug))
 return (r if r!='.' else '.')+'/'
def image_src(lang,slug,name):return posixpath.relpath('assets/images/'+name,path_for(lang,slug))
def asset_src(lang,slug,name):return posixpath.relpath('assets/'+name,path_for(lang,slug))
def link(lang,slug,dest,label,cls='mini-link',icon='arrow-right'):
 return f'<a class="{cls}" href="{E(href(lang,slug,dest))}">{E(label)} {ic(icon)}</a>'
def photo(lang,slug,filename,alt='',cls='',lazy=True):
 return f'<img class="{cls}" src="{E(image_src(lang,slug,filename))}" alt="{E(alt)}" loading="{"lazy" if lazy else "eager"}" decoding="async">'
def section_title(lang,kicker,title,desc='',center=False):
 return f'<div class="section-title{" centered" if center else ""}"><span class="eyebrow">{E(kicker)}</span><h2>{E(title)}</h2>{f"<p>{E(desc)}</p>" if desc else ""}</div>'
def section_header(lang,kicker,title,desc,slug,dest=None,button=None):
 return '<div class="section-heading-row">'+section_title(lang,kicker,title,desc)+(link(lang,slug,dest,button) if dest is not None else '')+'</div>'
def note(lang):
 return ''

def phone_entries():
 entries=[{'number':CFG['phone'],'display':CFG.get('phone_display',CFG['phone'])}]
 for item in CFG.get('additional_phones',[]):
  if isinstance(item,dict):
   num=item.get('number') or item.get('phone') or ''
   disp=item.get('display') or num
  else:
   num=item;disp=item
  if num: entries.append({'number':num,'display':disp})
 return entries

def phone_text(sep=' / '):
 return sep.join(x['display'] for x in phone_entries())

def phone_anchor_list(include_icon=True):
 anchors=[]
 for item in phone_entries():
  icon=(ic('phone')+' ') if include_icon else ''
  anchors.append(f'<a href="tel:{E(item['number'])}">{icon}{E(item['display'])}</a>')
 return ''.join(anchors)

def leader_card(lang,slug,leader):
 role=s(*ROLES[leader['role']],lang)
 name=leader['name_'+lang]
 msg=leader.get('message_'+lang,'')
 featured=leader['role']=='chairman'
 return f"""<article class="leadership-row{' chairman-row' if featured else ''}"><div class="leadership-portrait">{photo(lang,slug,leader['photo'],name+' — '+role)}</div><div class="leadership-copy"><span class="eyebrow">{E(s('MESSAGE FROM THE '+role.upper(),'বার্তা · '+role,lang))}</span><span class="leadership-role">{E(role)}</span><h2>{E(name)}</h2><div class="message-rule"></div><p class="leadership-message">{E(msg)}</p><span class="leadership-signature">{E(name)} <span>· {E(role)}</span></span></div></article>"""

