 logo=photo(lang,slug,'logo.png',s('Pallabi Hospital logo','পল্লবী হাসপাতালের লোগো',lang),'',False)
 brand=f'<a class="brand" href="{E(href(lang,slug))}" aria-label="{E(s("Go to homepage","হোমপেজে যান",lang))}">{logo}<span class="brand-text"><strong>{s("PALLABI HOSPITAL","পল্লবী হাসপাতাল",lang)}<br>{s("& DIAGNOSTIC CENTER","এন্ড ডায়াগনস্টিক সেন্টার",lang)}</strong><small>YOUR HEALTH, OUR EXPERTISE</small></span></a>'
