def legal_page(lang,slug):
 data=POLICIES[slug][lang]
 date=s('Updated 12 October 2026','সর্বশেষ হালনাগাদ: ১২ অক্টোবর ২০২৬',lang)
 intro=page_hero(lang,slug,data['intro'])
 sections=data['sections']
 guide=s('On this page','এই পৃষ্ঠায়',lang)
 nav=''.join(f'<a href="#section-{i+1}"><span>{i+1:02d}</span>{E(x[0])}</a>' for i,x in enumerate(sections))
 blocks=''.join(f'<section class="policy-section" id="section-{i+1}" aria-labelledby="policy-heading-{i+1}"><h2 id="policy-heading-{i+1}">{E(title)}</h2><p>{E(body)}</p></section>' for i,(title,body) in enumerate(sections))
 phone_items=''.join(f'<a class="policy-contact-link" href="tel:{E(n["number"])}">{ic("phone")} {E(n["display"])}</a>' for n in phone_entries())
 email=f'<a class="policy-contact-link" href="mailto:{E(CFG["email"])}">{ic("mail")} {E(CFG["email"])}</a>'
 contact=f'<div class="policy-contact"><span class="eyebrow">{E(s("GET IN TOUCH","যোগাযোগ",lang))}</span><h2>{E(data["contact_title"])}</h2><p>{E(data["contact_description"])}</p><div class="policy-contact-actions">{phone_items}{email}</div></div>'
 return intro+f'''<section class="section policy-page"><div class="container"><div class="policy-overview"><div class="policy-overview-icon">{ic('shield' if slug=='privacy-policy' else 'file' if slug=='terms-and-conditions' else 'handshake')}</div><div><span class="policy-meta">{E(date)} · Pallabi Hospital &amp; Diagnostic Center</span><p>{E(data['summary'])}</p></div></div><div class="policy-layout"><aside class="policy-sidebar"><nav class="policy-toc" aria-label="{E(guide)}"><h2>{E(guide)}</h2>{nav}</nav></aside><div class="policy-article">{blocks}{contact}</div></div></div></section>'''

PAGES={'':home,'about':about_page,'vision-mission':vision_page,'management':management_page,'leadership':management_page,'departments':departments_page,'diagnostics':diagnostics_page,'facilities':facilities_page,'inpatient-care':inpatient_page,'outpatient-care':outpatient_page,'health-packages':packages_page,'appointments':appointments_page,'gallery':gallery_page,'news':news_page,'health-insights':insights_page,'patient-guide':patient_guide_page,'faq':faq_page,'careers':careers_page,'contact':contact_page,'privacy-policy':legal_page,'terms-and-conditions':legal_page,'accessibility':legal_page}

def build():
 for lang in ['bn','en']:
  old_doctors=OUT/lang/'doctors'
  if old_doctors.exists():shutil.rmtree(old_doctors)
  for slug in PAGE_KEYS:
   content=PAGES[slug](lang,slug)
   dest=OUT/path_for(lang,slug)
   dest.mkdir(parents=True,exist_ok=True)
   (dest/'index.html').write_text(wrap(lang,slug,content),encoding='utf-8')
 # Bangla is default; a root link to both languages stays visible when JS is disabled.
 (OUT/'index.html').write_text('<!doctype html><html lang="bn"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="0; url=bn/index.html"><title>Pallabi Hospital & Diagnostic Center</title></head><body><p><a href="bn/">বাংলা</a> · <a href="en/">English</a></p></body></html>',encoding='utf-8')
 (OUT/'404.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page not found</title><link rel="stylesheet" href="assets/style.css"><main style="max-width:720px;margin:15vh auto;padding:2rem;text-align:center"><h1>404 — Page not found</h1><p>This page may have moved. Choose a language below to return to the hospital website.</p><a href="bn/">বাংলা</a> · <a href="en/">English</a></main></html>',encoding='utf-8')
 if CFG.get('website_url'):
  import xml.sax.saxutils as xs
  rooturl=CFG['website_url'].rstrip('/')
  urls=[f'<url><loc>{xs.escape(rooturl+"/"+path_for(lang,slug)+"/")}</loc></url>' for lang in ['bn','en'] for slug in PAGE_KEYS]
  (OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(urls)+'</urlset>',encoding='utf-8')
 elif (OUT/'sitemap.xml').exists(): (OUT/'sitemap.xml').unlink()
 (OUT/'robots.txt').write_text(('User-agent: *\nDisallow: /\n' if CFG.get('preview_mode',True) else 'User-agent: *\nAllow: /\n'),encoding='utf-8')
 print('Generated', len(PAGE_KEYS)*2+2, 'HTML pages')
if __name__=='__main__':build()
